use std::{io::{Read,Write},net::TcpListener,sync::mpsc,thread,time::Duration};
use tokio::sync::watch;
use zwen_core::{provider::{ProviderConfig,ApiKey},completion::FinishReason};
use zwen_transport::{client,stream_text,Error};
fn runtime()->tokio::runtime::Runtime{tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()}
fn server(status:&str,content_type:&str,body:Vec<u8>,hold:bool)->(ProviderConfig,mpsc::Receiver<Vec<u8>>,thread::JoinHandle<()>){
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();let port=listener.local_addr().unwrap().port();let status=status.to_owned();let content_type=content_type.to_owned();let(tx,rx)=mpsc::channel();
 let task=thread::spawn(move||{listener.set_nonblocking(true).unwrap();let began=std::time::Instant::now();let mut socket=loop{match listener.accept(){Ok((s,_))=>break s,Err(e)if e.kind()==std::io::ErrorKind::WouldBlock&&began.elapsed()<Duration::from_secs(5)=>thread::sleep(Duration::from_millis(5)),Err(_)=>return}};socket.set_read_timeout(Some(Duration::from_secs(2))).unwrap();
 let mut request=Vec::new();let mut b=[0;4096];loop{let n=socket.read(&mut b).unwrap();if n==0{break;}request.extend_from_slice(&b[..n]);if let Some(i)=request.windows(4).position(|v|v==b"\r\n\r\n"){let head=String::from_utf8_lossy(&request[..i]);let size:usize=head.lines().find_map(|line|line.to_ascii_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse().unwrap())).unwrap();if request.len()>=i+4+size{break;}}}
 let _=tx.send(request);let header=format!("HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nLocation: http://127.0.0.1:9/forbidden\r\nConnection: close\r\n\r\n");let _=socket.write_all(header.as_bytes());
 for bytes in body.chunks(3){if socket.write_all(bytes).is_err(){break;}}
 let _=socket.flush();if hold{thread::sleep(Duration::from_millis(350));}
 });(ProviderConfig::new(&format!("http://127.0.0.1:{port}/v1"),"fixture-model","KEY").unwrap(),rx,task)
}
fn response(text:&str,finished:bool)->Vec<u8>{let mut s=format!("data: {}\r\n\r\n",serde_json::json!({"choices":[{"index":0,"delta":{"content":text},"finish_reason":null}]}));if finished{s.push_str(&format!("data: {}\n\ndata: [DONE]\n\n",serde_json::json!({"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]})));}s.into_bytes()}
#[test] fn real_http_stream_is_decoded_and_request_is_exact(){runtime().block_on(async{let(cfg,request,task)=server("200 OK","text/event-stream; charset=utf-8",response("中文🙂",true),false);let(_tx,rx)=watch::channel(false);let mut text=String::new();let result=stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"quote \"\n中文",rx,|s|{text.push_str(s);Ok(())}).await;assert_eq!(result,Ok(FinishReason::Stop));assert_eq!(text,"中文🙂");let req=request.recv().unwrap();let i=req.windows(4).position(|b|b==b"\r\n\r\n").unwrap();let headers=String::from_utf8_lossy(&req[..i]).to_lowercase();assert!(headers.starts_with("post /v1/chat/completions "));assert!(headers.contains("authorization: bearer fixture-token"));let body:serde_json::Value=serde_json::from_slice(&req[i+4..]).unwrap();assert_eq!(body["messages"][0]["content"],"quote \"\n中文");assert_eq!(body["stream"],true);task.join().unwrap();});}
#[test] fn partial_eof_is_an_error_but_received_text_survives(){runtime().block_on(async{let(cfg,_,task)=server("200 OK","text/event-stream",response("partial",false),false);let(_tx,rx)=watch::channel(false);let mut text=String::new();let result=stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"q",rx,|s|{text.push_str(s);Ok(())}).await;assert_eq!(result,Err(Error::Protocol));assert_eq!(text,"partial");task.join().unwrap();});}
#[test] fn http_failures_and_redirects_are_not_retried_or_followed(){runtime().block_on(async{for status in ["401 Unauthorized","429 Too Many Requests","302 Found"]{let(cfg,_,task)=server(status,"application/json",b"secret-value".to_vec(),false);let(_tx,rx)=watch::channel(false);let result=stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"q",rx,|_|panic!("Error body was emitted")).await;assert_eq!(result,Err(Error::Http(status[..3].parse().unwrap())));assert!(!format!("{result:?}").contains("secret-value"));task.join().unwrap();}});}
#[test] fn cancellation_interrupts_an_idle_response(){runtime().block_on(async{let(cfg,_,task)=server("200 OK","text/event-stream",response("one",false),true);let(tx,rx)=watch::channel(false);let began=std::time::Instant::now();let result=stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"q",rx,|_|{tx.send(true).unwrap();Ok(())}).await;assert_eq!(result,Err(Error::Cancelled));assert!(began.elapsed()<Duration::from_millis(300));task.join().unwrap();});}
#[test] fn wrong_content_type_never_reaches_rendering(){runtime().block_on(async{let(cfg,_,task)=server("200 OK","text/html",b"<script>secret</script>".to_vec(),false);let(_tx,rx)=watch::channel(false);assert_eq!(stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"q",rx,|_|panic!("HTML rendered")).await,Err(Error::Protocol));task.join().unwrap();});}
#[test] fn explicit_context_is_sent_in_order(){runtime().block_on(async{use zwen_core::completion::{Message,Role};let(cfg,request,task)=server("200 OK","text/event-stream",response("answer",true),false);let messages=vec![Message{role:Role::User,content:"prior".into(),images:Vec::new()},Message{role:Role::Assistant,content:"prior answer".into(),images:Vec::new()},Message{role:Role::User,content:"follow-up".into(),images:Vec::new()}];let(_tx,rx)=watch::channel(false);let result=zwen_transport::stream_messages(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),&messages,rx,|_|Ok(())).await;assert_eq!(result,Ok(FinishReason::Stop));let req=request.recv().unwrap();let i=req.windows(4).position(|v|v==b"\r\n\r\n").unwrap();let body:serde_json::Value=serde_json::from_slice(&req[i+4..]).unwrap();assert_eq!(body["messages"][0]["content"],"prior");assert_eq!(body["messages"][1]["role"],"assistant");assert_eq!(body["messages"][2]["content"],"follow-up");task.join().unwrap();});}
#[test] fn images_render_official_content_parts_and_are_bounded(){runtime().block_on(async{use zwen_core::completion::{Message,Role};let(cfg,request,task)=server("200 OK","text/event-stream",response("seen",true),false);let messages=vec![Message{role:Role::User,content:"这张截图里有什么？".into(),images:vec!["QUJD".into(),"REVG".into()]}];let(_tx,rx)=watch::channel(false);let result=zwen_transport::stream_messages(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),&messages,rx,|_|Ok(())).await;assert_eq!(result,Ok(FinishReason::Stop));let req=request.recv().unwrap();let i=req.windows(4).position(|v|v==b"\r\n\r\n").unwrap();let body:serde_json::Value=serde_json::from_slice(&req[i+4..]).unwrap();let content=body["messages"][0]["content"].as_array().unwrap();assert_eq!(content[0],serde_json::json!({"type":"image_url","image_url":{"url":"QUJD"}}));assert_eq!(content[1],serde_json::json!({"type":"image_url","image_url":{"url":"REVG"}}));assert_eq!(content[2],serde_json::json!({"type":"text","text":"这张截图里有什么？"}));task.join().unwrap();});}
#[test] fn invalid_image_payloads_are_rejected_before_any_request(){runtime().block_on(async{use zwen_core::completion::{Message,Role};let(cfg,request,task)=server("200 OK","text/event-stream",response("never",true),false);let cases=vec![
 Message{role:Role::User,content:"q".into(),images:vec![String::new()]},
 Message{role:Role::User,content:"q".into(),images:vec!["not base64!".into()]},
 Message{role:Role::User,content:"q".into(),images:vec!["QQ==".into();9]},
];for messages in cases{let(_tx,rx)=watch::channel(false);let result=zwen_transport::stream_messages(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),std::slice::from_ref(&messages),rx,|_|panic!("Invalid payload sent")).await;assert_eq!(result,Err(Error::InvalidInput));}
 assert!(request.recv_timeout(Duration::from_millis(300)).is_err());task.join().unwrap();});}
#[test] fn provider_error_code_is_preserved_without_the_message(){runtime().block_on(async{let(cfg,_,task)=server("429 Too Many Requests","application/json",br#"{"error":{"code":"1302","message":"private-secret-value"}}"#.to_vec(),false);let(_tx,rx)=watch::channel(false);let result=stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"q",rx,|_|panic!("Error body emitted")).await;let message=result.unwrap_err().to_string();assert!(message.contains("429"));assert!(message.contains("1302"));assert!(!message.contains("private-secret-value"));task.join().unwrap();});}
#[test]fn permanent_string_quota_errors_never_become_temporary_429(){runtime().block_on(async{for body in [br#"{"error":{"code":"insufficient_quota","message":"private-quota-body"}}"#.to_vec(),br#"{"error":{"type":"billing_hard_limit_reached"}}"#.to_vec()]{let(cfg,_,task)=server("429 Too Many Requests","application/json\r\nRetry-After: 1",body,false);let(_tx,rx)=watch::channel(false);let error=stream_text(&client().unwrap(),&cfg,&ApiKey::new("fixture-token").unwrap(),"q",rx,|_|panic!("error text emitted")).await.unwrap_err();assert_eq!(zwen_transport::retry::RetryPolicy::default().delay(&error,1),None);assert!(!error.to_string().contains("private-quota-body"));task.join().unwrap();}});}
